  "implementation": "def solve(case):
    # Validate and parse input
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required fields: nodes, required_symbols')
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('nodes must be a list, required_symbols must be a list')
    # Build maps
    node_map = {}
    children_map = {}
    for n in nodes:
        if not isinstance(n, dict):
            raise ValueError('each node must be a dict')
        if 'id' not in n or 'parent' not in n or 'depth' not in n or 'removable' not in n or 'symbol' not in n:
            raise ValueError('node missing required fields')
        nid = n['id']
        if not isinstance(nid, str):
            raise ValueError('node id must be string')
        node_map[nid] = n
        parent = n['parent']
        children_map.setdefault(parent, []).append(nid)
    # Identify root
    root_id = None
    for nid, n in node_map.items():
        if n['parent'] is None:
            if root_id is not None:
                raise ValueError('multiple root nodes')
            root_id = nid
    if root_id is None:
        raise ValueError('no root node')
    # Check all parents exist (except None)
    for n in nodes:
        p = n['parent']
        if p is not None and p not in node_map:
            raise ValueError(f'parent {p} not found')
    removed = set()
    removed_order = []
    # Process nodes depth descending, tie-break by id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if not n['removable']:
            continue
        if nid == root_id:
            continue
        if n['symbol'] in required_symbols:
            continue
        # All children must already be removed
        child_ids = children_map.get(nid, [])
        if any(cid not in removed for cid in child_ids):
            continue
        # Removal is safe
        removed.add(nid)
        removed_order.append(nid)
    # Build retained list sorted
    retained_ids = sorted([n['id'] for n in nodes if n['id'] not in removed])
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_ids}"
}
